//! The built-in image: what sa-game's arena starts with when no `gta_sa.exe` is read.
//!
//! The data comes from the exe's initialised data sections (0x858000..0xCB1000), stored as runs of bytes at
//! their original addresses with long zero stretches left out (the arena is zero-filled before the runs are
//! copied in, as `.bss` is). The import table and the import call sites replace what sa-game used to parse out
//! of the exe's headers and `.text`. Everything but this file is generated by `tools/gen/image_rs.py`.

mod generated;

pub use generated::{CALL_SITES, IMPORTS};

static BYTES: &[u8] = include_bytes!("../image.bin");

/// First and one-past-last address the image covers.
pub const RANGE: (u32, u32) = (0x0085_8000, 0x00CB_1000);

/// The non-zero stretches of the image: `(address, bytes)`, sorted by address.
pub fn runs() -> impl Iterator<Item = (u32, &'static [u8])> {
    generated::RUNS.iter().scan(0usize, |off, &(addr, len)| {
        let b = &BYTES[*off..*off + len as usize];
        *off += len as usize;
        Some((addr, b))
    })
}

/// The IAT cell a `call dword ptr [cell]` at `site` reads, for the call sites the sources declare.
pub fn call_site_cell(site: u32) -> Option<u32> {
    CALL_SITES.binary_search_by_key(&site, |&(s, _)| s).ok().map(|i| CALL_SITES[i].1)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn runs_cover_the_blob_in_order_inside_the_range() {
        let total: usize = generated::RUNS.iter().map(|&(_, n)| n as usize).sum();
        assert_eq!(total, BYTES.len());
        let mut end = RANGE.0;
        for (a, b) in runs() {
            assert!(a >= end && a as usize + b.len() <= RANGE.1 as usize, "{a:#x}");
            end = a + b.len() as u32;
        }
    }

    #[test]
    fn tables_sorted_and_inside_the_image() {
        assert!(CALL_SITES.windows(2).all(|w| w[0].0 < w[1].0));
        assert!(IMPORTS.iter().all(|&(c, _)| (RANGE.0..RANGE.1).contains(&c)));
    }
}
